Generated SQL:
SELECT c."customerName", e."firstName" || ' ' || e."lastName" AS "repName"
FROM "customers" c
LEFT JOIN "employees" e ON c."salesRepEmployeeNumber" = e."employeeNumber";

SELECT o."orderNumber", o."orderDate", o."requiredDate", o."shippedDate", o."status", o."comments", o."customerNumber", c."city"
FROM "orders" AS o
JOIN "customers" AS c ON o."customerNumber" = c."customerNumber";
